<?php
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); $t=fn($k)=>$this->objLanguage->languageText('mod_registration_service_'.$k,'registration-service');
$u=fn($p=array())=>$e(html_entity_decode($this->uri($p,'registration-service'),ENT_QUOTES,'UTF-8')); $abuse=$recoveryAbuse??array();
?>
<main class="chisimba-workspace registration-service" aria-labelledby="recovery-request-title"><h1 id="recovery-request-title"><?php echo $e($t('recovery_title')); ?></h1><?php if(!empty($recoveryRequested)): ?><div class="success" role="status"><?php echo $e($t('recovery_requested')); ?></div><?php else: ?><p><?php echo $e($t('recovery_intro')); ?></p><?php if(!empty($recoveryError)): ?><div class="error" role="alert"><?php echo $e($t('error_invalid_request')); ?></div><?php endif; ?><form method="post" action="<?php echo $u(array('action'=>'requestrecovery')); ?>"><input type="hidden" name="csrf_token" value="<?php echo $e($recoveryRequestCsrf??''); ?>"><input type="hidden" name="abuse_issued_at" value="<?php echo $e($abuse['issued_at']??''); ?>"><input type="hidden" name="abuse_nonce" value="<?php echo $e($abuse['nonce']??''); ?>"><input type="hidden" name="abuse_signature" value="<?php echo $e($abuse['signature']??''); ?>"><div hidden aria-hidden="true"><label for="recovery-website">Website</label><input id="recovery-website" name="website" type="text" tabindex="-1" autocomplete="off"></div><section class="chisimba-form-section"><label for="recovery-email"><?php echo $e($t('email')); ?></label><input id="recovery-email" name="email_address" type="email" autocomplete="email" required></section><div class="chisimba-form-actions"><button class="button" type="submit"><?php echo $e($t('send_recovery')); ?></button></div></form><?php endif; ?></main>
